insert into lr_explanation_steps (explanation_id,position,label,body) select v.e,v.p,v.l,v.b from (values
('42bc61ac-a0e5-41af-84c5-b5be13a99497'::uuid,3,'Goal','Look for an answer that rules out a volcanic source to the north of the boulder, so the southward-moving glacier has nowhere to start. An answer giving another way the boulder arrived would also work. Be careful with answers about the nearest source or about distance: the conclusion only needs some source to the north, not the closest one.'),
('fd9e2842-7328-4f9b-a5be-91c166ba5213'::uuid,3,'Goal','Look for an answer saying the intellectual skills society values most are not computational, so a computer''s speed at computation does not reach them. An answer showing a relevant difference between the Industrial Revolution case and the computer case would also weaken, but expect the first.')
